package envtemplate

import (
	"fmt"
	"strconv"
	"strings"

	"github.com/compose-spec/compose-go/v2/dotenv"
)

func render(inputs []*input, target Target, relative func(string) string) (string, error) {
	files := make([]string, len(target.Files))
	for i, file := range target.Files {
		files[i] = relative(file)
	}
	lines := []string{
		"# Generated by stacklint; do not edit.",
		"# Compose files: " + strings.Join(files, ", "),
		"# Regenerate with: stacklint env generate " + target.Stack.RelPath + " --variant " + target.Variant,
		"# Uncomment only intentional overrides; defaults remain in Compose.",
	}
	groups := []string{""}
	for _, item := range inputs {
		if item.Source == "" && hasEffective(item) && item.Group != "" {
			exists := false
			for _, group := range groups {
				if group == item.Group {
					exists = true
				}
			}
			if !exists {
				groups = append(groups, item.Group)
			}
		}
	}
	for _, group := range groups {
		heading := false
		for _, item := range inputs {
			if item.Source != "" || !hasEffective(item) || item.Group != group {
				continue
			}
			if group != "" && !heading {
				lines = append(lines, "", "# Module inputs: "+group)
				heading = true
			}
			entry, err := renderEntry(item, false, len(files) > 1)
			if err != nil {
				return "", err
			}
			lines = append(lines, "")
			lines = append(lines, entry...)
		}
	}
	heading := false
	for _, item := range inputs {
		if item.Source != "" || hasEffective(item) {
			continue
		}
		if !heading {
			lines = append(lines, "", "# Loading-stage inputs (referenced before Compose merge).")
			heading = true
		}
		entry, err := renderEntry(item, true, true)
		if err != nil {
			return "", err
		}
		lines = append(lines, "")
		lines = append(lines, entry...)
	}
	heading = false
	for _, item := range inputs {
		if item.Source == "" {
			continue
		}
		if !heading {
			lines = append(lines, "", "# Supplied inputs (reference only; no assignment entries).")
			heading = true
		}
		lines = append(lines, "# "+item.Name+": "+item.Source)
		for _, description := range item.Descriptions {
			lines = append(lines, commentLines(description)...)
		}
	}
	return strings.Join(lines, "\n") + "\n", nil
}

func hasEffective(item *input) bool {
	for _, occurrence := range item.Occurrences {
		if occurrence.Effective {
			return true
		}
	}
	return false
}

func renderEntry(item *input, loading, showFile bool) ([]string, error) {
	var lines []string
	for _, preamble := range item.Preambles {
		lines = append(lines, commentLines(preamble)...)
	}
	if len(item.Preambles) > 0 {
		lines = append(lines, "")
	}
	for _, description := range item.Descriptions {
		lines = append(lines, commentLines(description)...)
	}
	var behavior *Behavior
	simple := true
	required, nonempty := false, false
	inactiveRequired := false
	for _, occurrence := range item.Occurrences {
		if occurrence.Behavior != nil && occurrence.Behavior.Required {
			required = true
			nonempty = nonempty || occurrence.Behavior.Nonempty
			if !occurrence.Effective {
				inactiveRequired = true
			}
		}
	}
	for _, occurrence := range item.Occurrences {
		if !occurrence.Effective && !loading {
			continue
		}
		if occurrence.Behavior == nil {
			simple = false
			continue
		}
		if behavior == nil {
			behavior = occurrence.Behavior
		} else if !sameBehavior(behavior, occurrence.Behavior) {
			if !loading && !required {
				return nil, fmt.Errorf("input %s has inconsistent default behavior in effective Compose fields; unify the expressions", item.Name)
			}
			simple = false
		}
	}
	if loading || inactiveRequired || !simple || behavior == nil {
		for _, occurrence := range item.Occurrences {
			if occurrence.Expression == "" {
				if occurrence.Path == "include.env_file" {
					lines = append(lines, "# Dependency of include env_file "+occurrence.File+"; static placeholders are not deployment defaults.")
				} else {
					lines = append(lines, "# Optional passthrough at "+occurrence.File+":"+occurrence.Path+".")
				}
				continue
			}
			position := occurrence.Path
			if showFile || occurrence.File != item.Occurrences[0].File {
				position = occurrence.File + ":" + position
			}
			label := "# Expression at "
			if !occurrence.Effective && !loading {
				label = "# Loading-stage expression at "
			}
			lines = append(lines, label+position+":")
			lines = append(lines, commentLines(occurrence.Expression)...)
		}
	}
	if required {
		if nonempty {
			lines = append(lines, "# Required; must not be empty.")
		} else {
			lines = append(lines, "# Required; may be empty.")
		}
		lines = append(lines, item.Name+"=")
	} else if simple && !loading && behavior != nil && behavior.Default != nil {
		if !behavior.EmptyUsesDefault {
			lines = append(lines, "# Default applies only when unset, not when empty.")
		}
		assignment, err := encodeAssignment(item.Name, *behavior.Default)
		if err != nil {
			return nil, err
		}
		lines = append(lines, "# "+assignment)
	} else {
		lines = append(lines, "# "+item.Name+"=")
	}
	return lines, nil
}

func sameBehavior(a, b *Behavior) bool {
	if a.Required != b.Required || a.Nonempty != b.Nonempty || a.EmptyUsesDefault != b.EmptyUsesDefault {
		return false
	}
	if a.Default == nil || b.Default == nil {
		return a.Default == nil && b.Default == nil
	}
	return *a.Default == *b.Default
}

func encodeAssignment(name, value string) (string, error) {
	candidates := []string{}
	if !strings.ContainsAny(value, "\r\n'\"\\$# \t") {
		candidates = append(candidates, name+"="+value)
	}
	candidates = append(candidates, name+"='"+strings.ReplaceAll(value, "'", "\\'")+"'", name+"="+strconv.Quote(strings.ReplaceAll(value, "$", "\\$")))
	for _, candidate := range candidates {
		parsed, err := dotenv.ParseWithLookup(strings.NewReader(candidate+"\n"), func(string) (string, bool) { return "", false })
		if err == nil && len(parsed) == 1 && parsed[name] == value {
			return candidate, nil
		}
	}
	return "", fmt.Errorf("cannot round-trip dotenv assignment for %s", name)
}

func commentLines(text string) []string {
	parts := strings.Split(text, "\n")
	for i, part := range parts {
		if part == "" {
			parts[i] = "#"
		} else {
			parts[i] = "# " + part
		}
	}
	return parts
}
